<?php
declare(strict_types=1);
require_once __DIR__ . '/business/config/role_mfa.php';

$error=null;$success=null;$user=null;$csrf='';$account=null;$enabled=false;$setupSecret='';$newCodes=[];$remaining=0;
function mfas_when(?string $v):string{if(!$v)return '—';$t=strtotime($v);return $t?date('d M Y, h:i A',$t):$v;}
function mfas_group_secret(string $s):string{return trim(chunk_split($s,4,' '));}
try{
    $pdo=role_portal_db();role_mfa_ensure($pdo);security_step17_session_start();
    if(role_mfa_pending_exists()){header('Location: mfa_verify.php');exit;}
    $user=security_step17_session_user($pdo,true);if(!$user){header('Location: login.php');exit;}
    if((int)($user['must_change_password']??0)===1){header('Location: change_password.php?required=1');exit;}
    $ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];$userId=(int)$user['id'];$csrf=security_step17_csrf();
    $account=role_mfa_account($pdo,$orgId,$userId);$enabled=$account!==null&&(int)$account['is_enabled']===1;

    if(!$enabled){
        $setupKey='hwc_mfa_setup_'.$userId;
        if(empty($_SESSION[$setupKey]))$_SESSION[$setupKey]=role_mfa_generate_secret();
        $setupSecret=(string)$_SESSION[$setupKey];
    }

    if($_SERVER['REQUEST_METHOD']==='POST'){
        security_step17_verify_csrf((string)($_POST['csrf']??''));$action=(string)($_POST['action']??'');
        if($action==='enable'){
            if($enabled)throw new RuntimeException('Authenticator verification is already enabled.');
            $setupKey='hwc_mfa_setup_'.$userId;$setupSecret=(string)($_SESSION[$setupKey]??'');if($setupSecret==='')throw new RuntimeException('Authenticator setup expired. Refresh this page and try again.');
            $newCodes=role_mfa_enable($pdo,$user,(string)($_POST['current_password']??''),$setupSecret,(string)($_POST['code']??''));unset($_SESSION[$setupKey]);$success='Two-step verification is now enabled. Save the recovery codes below before leaving this page.';
        }elseif($action==='regenerate'){
            if(!$enabled)throw new RuntimeException('Enable authenticator verification first.');
            $newCodes=role_mfa_regenerate_recovery($pdo,$user,(string)($_POST['current_password']??''),(string)($_POST['code']??''));$success='New recovery codes created. Every previous recovery code is now invalid.';
        }elseif($action==='disable'){
            if(!$enabled)throw new RuntimeException('Authenticator verification is already disabled.');
            role_mfa_disable($pdo,$user,(string)($_POST['current_password']??''),(string)($_POST['code']??''));$success='Two-step verification disabled. Other active sessions were revoked.';
        }
        $account=role_mfa_account($pdo,$orgId,$userId);$enabled=$account!==null&&(int)$account['is_enabled']===1;
        if(!$enabled){$setupKey='hwc_mfa_setup_'.$userId;if(empty($_SESSION[$setupKey]))$_SESSION[$setupKey]=role_mfa_generate_secret();$setupSecret=(string)$_SESSION[$setupKey];}else{$setupSecret='';}
    }
    if($enabled)$remaining=role_mfa_recovery_remaining($pdo,$orgId,$userId);
}catch(Throwable $e){$error=$e->getMessage();}
$home=$user?role_portal_home($user):'login.php';$uri=(!$enabled&&$user&&$setupSecret!=='')?role_mfa_otpauth_uri((string)$user['email'],$setupSecret):'';
?><!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Two-Step Verification - Healthcare Wellness Club</title><link rel="stylesheet" href="pages/auth.css"><style>
.mfa-grid{display:grid;grid-template-columns:minmax(310px,.9fr) minmax(0,1.1fr);gap:14px}.mfa-card{border:1px solid var(--auth-line);border-radius:18px;background:rgba(255,255,255,.94);padding:19px;box-shadow:0 9px 27px rgba(36,72,52,.055)}.mfa-card.mint{background:linear-gradient(145deg,#fff,var(--auth-mint))}.mfa-card.blue{background:linear-gradient(145deg,#fff,var(--auth-blue))}.mfa-card.full{grid-column:1/-1}.mfa-card h2{margin:0;font-size:1.04rem}.mfa-card>p{margin:6px 0 0;color:var(--auth-muted);font-size:.78rem;line-height:1.55}.setup-secret{margin-top:13px;padding:14px;border:1px dashed #b9d4c5;border-radius:13px;background:#fff}.setup-secret code{display:block;margin-top:7px;font-size:1.05rem;letter-spacing:.08em;word-break:break-all}.uri-box{width:100%;box-sizing:border-box;margin-top:9px;padding:10px;border:1px solid #d9e5de;border-radius:10px;background:#f8faf9;font-size:.67rem}.recovery-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:12px}.recovery-code{padding:10px;border:1px solid #d7e4dd;border-radius:10px;background:#fff;text-align:center;font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-weight:800;font-size:.78rem}.status-box{display:grid;gap:8px;margin-top:13px}.status-row{display:flex;justify-content:space-between;gap:14px;padding:11px;border:1px solid #dfe8e3;border-radius:12px;background:#fff;font-size:.76rem}.danger-zone{margin-top:14px;padding:14px;border:1px solid #efd3d5;border-radius:14px;background:#fff5f5}.danger-zone h3{margin:0;font-size:.88rem}.danger-zone p{color:#7d6264;font-size:.72rem}.danger-zone button{background:#8a474c}.private-note{margin-top:12px;padding:12px;border-radius:12px;background:#fff8e8;color:#705f37;font-size:.73rem;line-height:1.55}@media(max-width:850px){.mfa-grid{grid-template-columns:1fr}.mfa-card.full{grid-column:auto}.recovery-grid{grid-template-columns:repeat(2,1fr)}.status-row{flex-direction:column}}
</style></head><body class="auth-page"><header class="auth-top"><a class="auth-brand" href="<?=$home?>"><img src="img/logo.png" alt="Healthcare Wellness Club"><span><strong>Healthcare Wellness Club</strong><small>Authenticator • Two-Step Verification</small></span></a><nav class="auth-nav"><a class="auth-btn" href="account.php">My Account</a><a class="auth-btn" href="trusted_devices.php">Trusted Devices</a><a class="auth-btn" href="<?=$home?>">My Portal</a><a class="auth-btn" href="logout.php">Sign Out</a></nav></header><main class="auth-shell"><section class="portal-head"><div><span class="role-badge">TWO-STEP SECURITY</span><h1>Authenticator Verification</h1><p>Add a second proof after your password. This uses standard time-based authenticator codes and does not depend on SMS or email delivery.</p></div><div class="account-list" style="min-width:220px"><div class="account-row"><span>Status</span><b><?=$enabled?'ENABLED':'DISABLED'?></b></div><?php if($enabled):?><div class="account-row"><span>Recovery codes left</span><b><?=$remaining?></b></div><?php endif;?></div></section><?php if($error):?><div class="auth-alert" role="alert"><?=security_step17_h($error)?></div><?php endif;?><?php if($success):?><div class="auth-alert good"><?=security_step17_h($success)?></div><?php endif;?>
<div class="mfa-grid"><?php if(!$enabled):?><section class="mfa-card mint"><h2>1. Add this account to your authenticator</h2><p>Use any authenticator app that supports standard TOTP accounts. Add it manually with the secret below.</p><div class="setup-secret"><span>Manual setup key</span><code><?=security_step17_h(mfas_group_secret($setupSecret))?></code><input class="uri-box" value="<?=security_step17_h($uri)?>" readonly aria-label="Authenticator setup URI"></div><div class="private-note"><strong>Keep this setup key private.</strong> Do not send it in chat, email or screenshots. It is shown here only so you can add the account to your authenticator.</div></section><section class="mfa-card blue"><h2>2. Confirm and enable</h2><p>Re-enter your current password, then type the 6-digit code currently shown by your authenticator.</p><form class="auth-form" method="post" autocomplete="off"><input type="hidden" name="csrf" value="<?=security_step17_h($csrf)?>"><input type="hidden" name="action" value="enable"><div class="auth-field"><label>Current Password</label><input class="auth-input" type="password" name="current_password" required autocomplete="current-password"></div><div class="auth-field"><label>6-digit Authenticator Code</label><input class="auth-input" name="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" pattern="[0-9]{6}" required></div><button class="auth-submit" type="submit">Enable Two-Step Verification</button></form></section><?php else:?><section class="mfa-card mint"><h2>Two-Step Verification Active</h2><p>Future password sign-ins must complete an authenticator or one-time recovery-code challenge.</p><div class="status-box"><div class="status-row"><span>Enabled</span><b><?=security_step17_h(mfas_when((string)($account['enabled_at']??'')))?></b></div><div class="status-row"><span>Last verified</span><b><?=security_step17_h(mfas_when((string)($account['last_verified_at']??'')))?></b></div><div class="status-row"><span>Unused recovery codes</span><b><?=$remaining?></b></div><div class="status-row"><span>Authenticator standard</span><b>TOTP • 6 digits • 30 seconds</b></div></div><div class="private-note">Your authenticator secret is encrypted at rest. Recovery codes are stored only as one-way hashes.</div></section><section class="mfa-card blue"><h2>Recovery Code Maintenance</h2><p>Regenerating creates a fresh set and immediately invalidates every previous recovery code.</p><form class="auth-form" method="post" autocomplete="off"><input type="hidden" name="csrf" value="<?=security_step17_h($csrf)?>"><input type="hidden" name="action" value="regenerate"><div class="auth-field"><label>Current Password</label><input class="auth-input" type="password" name="current_password" required autocomplete="current-password"></div><div class="auth-field"><label>Authenticator or Recovery Code</label><input class="auth-input" name="code" maxlength="16" required autocomplete="one-time-code"></div><button class="auth-submit" type="submit">Generate New Recovery Codes</button></form><div class="danger-zone"><h3>Disable Two-Step Verification</h3><p>This reduces sign-in protection. Current browser stays signed in, but other active sessions will be revoked.</p><form class="auth-form" method="post" autocomplete="off" onsubmit="return confirm('Disable two-step verification for this account?')"><input type="hidden" name="csrf" value="<?=security_step17_h($csrf)?>"><input type="hidden" name="action" value="disable"><div class="auth-field"><label>Current Password</label><input class="auth-input" type="password" name="current_password" required autocomplete="current-password"></div><div class="auth-field"><label>Authenticator or Recovery Code</label><input class="auth-input" name="code" maxlength="16" required autocomplete="one-time-code"></div><button class="auth-submit" type="submit">Disable Two-Step Verification</button></form></div></section><?php endif;?><?php if($newCodes):?><section class="mfa-card full"><h2>Save These Recovery Codes Now</h2><p>Each code works once. They will not be shown again after you leave or refresh this page.</p><div class="recovery-grid"><?php foreach($newCodes as $c):?><div class="recovery-code"><?=security_step17_h((string)$c)?></div><?php endforeach;?></div><div class="private-note"><strong>Store these privately</strong> in a password manager or another secure offline place. Do not send them to anyone and do not paste them into chat.</div></section><?php endif;?></div></main></body></html>
